// Norwegian audio playback.
//
// Clips are pre-generated by Piper and served from object storage. There is
// deliberately NO fallback to the browser's speech synthesis: substituting a
// different voice silently once hid a stopped MinIO for an entire session,
// and in listening practice it is worse than useless -- the dictation ladder
// is calibrated per clip, so a browser voice plays the wrong speed in the
// wrong voice while appearing to work. A clip that will not play is an error,
// and it is reported.

import { play, stop } from './playback'

export type AudioFailure = {
  url: string
  /** HTTP status where we got one; 0 when the request itself failed. */
  status: number
  message: string
}

type Listener = (failure: AudioFailure | null) => void

const listeners = new Set<Listener>()
let lastFailure: AudioFailure | null = null

/** Subscribe to playback failures. Returns an unsubscribe function. */
export function onAudioFailure(listener: Listener): () => void {
  listeners.add(listener)
  listener(lastFailure)
  return () => listeners.delete(listener)
}

export function clearAudioFailure(): void {
  lastFailure = null
  listeners.forEach((l) => l(null))
}

function report(failure: AudioFailure): void {
  lastFailure = failure
  // Logged as well as surfaced: the console is where this gets diagnosed.
  console.error(`[audio] ${failure.message} (${failure.status}) ${failure.url}`)
  listeners.forEach((l) => l(failure))
}

function describe(status: number): string {
  if (status === 503) return 'Audio storage is unavailable — the clip could not be loaded.'
  if (status === 404) return 'This clip has not been generated yet.'
  if (status === 401) return 'Session expired — log in again to hear audio.'
  if (status === 0) return 'Could not reach the server to load audio.'
  return `Audio request failed (${status}).`
}

// Every play attempt takes a token, and anything newer invalidates it.
// Loading a clip is asynchronous, so between the request and the player
// existing there is nothing for stopSpeech() to stop -- two overlapping calls
// would both reach play() and the clips would stack up. That happens on mount
// (StrictMode invokes effects twice) and whenever a speed chip is pressed.
let playToken = 0

export function stopSpeech(): void {
  playToken += 1 // abandon any clip still loading
  stop()
}

/**
 * Play a pre-generated clip.
 *
 * Fetched rather than handed to <audio> as a URL so the HTTP status is
 * visible: a media element that fails reports only "something went wrong",
 * which cannot distinguish an ungenerated clip from a dead object store. The
 * fetch is served from the browser cache on repeat plays, and having the whole
 * clip before starting also removes any chance of the player underrunning
 * mid-word. Playback itself goes through playback.ts, which levels every clip
 * to a common loudness and applies the master volume.
 *
 * `text` is kept for callers and accessibility; it is no longer spoken.
 */
export async function speak(_text: string, audioUrl?: string | null): Promise<void> {
  stopSpeech()
  const token = playToken
  const superseded = () => token !== playToken

  if (!audioUrl) {
    report({ url: '', status: 0, message: 'No audio is available for this text.' })
    return
  }

  let blob: Blob
  try {
    const resp = await fetch(audioUrl)
    if (superseded()) return
    if (!resp.ok) {
      report({ url: audioUrl, status: resp.status, message: describe(resp.status) })
      return
    }
    blob = await resp.blob()
  } catch {
    if (superseded()) return
    report({ url: audioUrl, status: 0, message: describe(0) })
    return
  }
  if (superseded()) return

  try {
    await play(blob, audioUrl)
    if (superseded()) return
    // A previous failure is stale once something plays.
    if (lastFailure) clearAudioFailure()
  } catch {
    report({ url: audioUrl, status: 0, message: 'The browser refused to play the clip.' })
  }
}
